inline V add(V a,V b){return {(a.x+b.x)%7,(a.y+b.y)%7,(a.z+b.z)%7};}inline V mul(V a,int s){return {a.x*s%7,a.y*s%7,a.z*s%7};}inline bool z(V a){return !a.x&&!a.y&&!a.z;}
vector<array<unsigned char,8>> SHORTS;
void genShort(int i,int left,array<unsigned char,8>&a){if(i==7){a[7]=left;SHORTS.push_back(a);return;}for(int x=0;x<=left;x++){a[i]=x;genShort(i+1,left-x,a);}}
void initShort(){array<unsigned char,8>a{};for(int L=1;L<=7;L++)genShort(0,L,a);}
bool shortfree(const array<V,8>&v,const array<int,8>&m){for(auto&a:SHORTS){V s{0,0,0};bool ok=true;for(int i=0;i<8;i++){if(a[i]>m[i]){ok=false;break;}if(a[i])s=add(s,mul(v[i],a[i]));}if(ok&&z(s))return false;}return true;}
inline bool addleq(uint32_t a,uint32_t b,const array<int,8>&m,uint32_t&out){uint32_t r=0,p=1;for(int i=0;i<8;i++){int x=a%7,y=b%7;a/=7;b/=7;if(x+y>m[i])return false;r+=(x+y)*p;p*=7;}out=r;return true;}
inline uint32_t complement(uint32_t a,const array<int,8>&m){uint32_t r=0,p=1;for(int i=0;i<8;i++){int x=a%7;a/=7;r+=(m[i]-x)*p;p*=7;}return r;}
void enumZero(const array<V,8>&v,const array<int,8>&m,int i,int len,V sum,uint32_t st,vector<uint32_t>&zs){if(len>13)return;if(i==8){if(len>=8&&z(sum))zs.push_back(st);return;}V cur=sum;uint32_t s=st;int mx=min(m[i],13-len);for(int r=0;r<=mx;r++){if(r){cur=add(cur,v[i]);s+=PW[i];}enumZero(v,m,i+1,len+r,cur,s,zs);}}
bool fourPack(const array<V,8>&v,const array<int,8>&m){vector<uint32_t>zs;enumZero(v,m,0,0,{0,0,0},0,zs);sort(zs.begin(),zs.end());zs.erase(unique(zs.begin(),zs.end()),zs.end());unordered_set<uint32_t>pairs;pairs.reserve(min<size_t>(5764801,zs.size()*max<size_t>(1,zs.size()/2)));for(size_t i=0;i<zs.size();i++)for(size_t j=i;j<zs.size();j++){uint32_t s;if(addleq(zs[i],zs[j],m,s))pairs.insert(s);}for(uint32_t s:pairs)if(pairs.count(complement(s,m)))return true;return false;}
struct Local{int a,r,s,h;};
int main(int argc,char**argv){initShort();if(argc<2)return 2;ifstream in(argv[1]);string line;vector<array<V,7>>R;while(getline(in,line)){if(line.empty())continue;stringstream ss(line);array<V,7>q;string t;for(int i=0;i<7;i++){ss>>t;replace(t.begin(),t.end(),',',' ');stringstream u(t);u>>q[i].x>>q[i].y>>q[i].z;}R.push_back(q);}int A=argc>2?stoi(argv[2]):0,B=argc>3?stoi(argv[3]):R.size();
 vector<Local>ls;for(int a=2;a<7;a++)for(int r=1;r<7;r++)for(int s=1;r+s<=6;s++){bool bad=false;for(int u=0;u<=r&&!bad;u++)for(int w=0;w<=s;w++)if(u+w&&(u+a*w)%7==0){bad=true;break;}if(bad)continue;auto x=make_tuple(a,r,s),y=make_tuple(INV[a],s,r);if(x>y)continue;ls.push_back({a,r,s,(r+a*s)%7});}if(ls.size()!=9)return 3;
 vector<array<int,7>>ds;array<int,7>d{};function<void(int,int)>gd=[&](int i,int left){if(i==6){d[6]=left;ds.push_back(d);return;}for(int x=0;x<=left;x++){d[i]=x;gd(i+1,left-x);}};gd(0,5);if(ds.size()!=462)return 3;
 long long total=0,sf=0,p4=0;auto t0=chrono::steady_clock::now();
 for(int ri=A;ri<B;ri++){auto q=R[ri];vector<array<int,7>>K;for(int a=1;a<7;a++)for(int b=1;b<7;b++)for(int c=1;c<7;c++)for(int e=1;e<7;e++)for(int f=1;f<7;f++)for(int g=1;g<7;g++){array<int,7>C={1,a,b,c,e,f,g};V s{0,0,0};for(int i=0;i<7;i++)s=add(s,mul(q[i],C[i]));if(z(s))K.push_back(C);}long long ltot=0,lsf=0,lbad=0;
  for(int j=0;j<7;j++)for(auto dd:ds){int tt[7];for(int i=0;i<7;i++)tt[i]=6-dd[i];for(auto L:ls)if(L.r+L.s==tt[j])for(auto C:K){total++;ltot++;array<V,8>v;array<int,8>m;int k=0;for(int i=0;i<7;i++)if(i==j){int lam=C[i]*INV[L.h]%7;v[k]=mul(q[i],lam);m[k++]=L.r;v[k]=mul(q[i],lam*L.a%7);m[k++]=L.s;}else{int lam=C[i]*INV[tt[i]]%7;v[k]=mul(q[i],lam);m[k++]=tt[i];}if(!shortfree(v,m))continue;sf++;lsf++;if(fourPack(v,m))p4++;else lbad++;}}
  if(ltot!=EXPECTED_TOTAL[ri]||lsf!=EXPECTED_SF[ri]){cerr<<"count mismatch class "<<ri<<" total="<<ltot<<" sf="<<lsf<<"\n";return 4;}cerr<<"class "<<ri<<" total="<<ltot<<" sf="<<lsf<<" bad="<<lbad<<"\n";if(lbad)return 1;}
 cout<<"classes="<<A<<".."<<B<<" total="<<total<<" shortfree="<<sf<<" pack4="<<p4<<" bad="<<(sf-p4)<<" seconds="<<chrono::duration<double>(chrono::steady_clock::now()-t0).count()<<"\n";return 0;}
